const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm'),path=require('node:path');
const root=path.join(__dirname,'..');
function engine(){const c={structuredClone,console};c.importScripts=()=>vm.runInContext(fs.readFileSync(path.join(root,'property-planner.js'),'utf8'),c);vm.createContext(c);vm.runInContext(fs.readFileSync(path.join(root,'simulation-worker.js'),'utf8').replace("require('./browser-entry.cjs');","globalThis.sim=require('./sim.cjs');globalThis.ranch=require('./ranch.cjs');globalThis.planner=require('./planner.cjs');globalThis.workers=require('./workers.cjs');"),c);return c;}
test('terrain-led property sites are dry, rotated, separated and connected across seeds',()=>{const c=engine();let prior;for(const [seed,size,horses] of [[43,540,6],[81,540,6],[127,540,6],[43,764,12]]){const p=c.sim.grow({seed,size,horses,mode:'grazing'},8);assert(p.valid,JSON.stringify(p.failures));const env=c.sim.environment(seed,size);assert(p.buildings.some(b=>Math.abs(Math.sin(b.angle*2))>.1));for(const b of p.buildings){for(const q of b.polygon)assert(env.dry(...q));for(const a of p.buildings)if(a!==b)assert(!c.FarmProperty.intersects(a,b));}assert(p.paths.every(p=>p.points.length>1));assert(p.pasture.area>=p.pasture.target);const centers=JSON.stringify(p.buildings.map(b=>[b.cx,b.cz]));assert.notEqual(centers,prior);prior=centers;}});
test('organic expansion admits every species and preserves serviced gates and material balances',()=>{const c=engine(),p=c.sim.grow({seed:43,size:540,horses:6,mode:'grazing'},8),s=c.ranch.create(p);c.planner.start(s,[['horse',6],['cow',2],['goat',2],['chicken',6]].map(([species,count])=>({species,count})));for(let i=0;i<20*8640&&!s.paused;i++)c.ranch.step(s);assert.equal(s.paused,null);assert.equal(s.animals.manager.residents.length,16);assert.equal(s.planner.adoptions.length,0);const f=c.ranch.frame(s);assert.equal(f.paddocks.length,4);assert.equal(f.paddocks.find(p=>p.species==='horse').buildingId,'shelter');for(const p of f.paddocks){assert.equal(p.fences.filter(f=>f.gate).length,1);const project=s.animals.projects.find(a=>a.id===p.id);assert(c.workers.route(s.workers,s.workers.depot,project.gateInside));}for(const b of f.buildings)assert.equal(b.stage,'complete');for(const v of Object.values(f.balances))if(typeof v==='number')assert(Math.abs(v)<1e-6,'Resource imbalance '+v);});
